// 2. GENERATE THE MISSING 900 QUESTIONS DYNAMICALLY
function generateMissingQuestions() {
    let currentCounts = { MC: 0, TF: 0, Short: 0, Code: 0 };
    
    // Count current
    CORE_QUESTIONS.forEach(q => currentCounts[q.section]++);
    
    // Generate MC up to 300
    while (currentCounts.MC < 300) {
        let a = Math.floor(Math.random() * 20) + 1;
        let b = Math.floor(Math.random() * 20) + 1;
        CORE_QUESTIONS.push({
            type: 'mc', section: 'MC',
            q: `What is the result of the following operation: ${a} + ${b} * 2?`,
            opts: [`${a + (b * 2)}`, `${(a + b) * 2}`, `${a + b}`, `${a * b}`],
            answer: `${a + (b * 2)}`
        });
        currentCounts.MC++;
    }

    // Generate TF up to 300
    while (currentCounts.TF < 300) {
        let a = Math.floor(Math.random() * 100);
        let b = Math.floor(Math.random() * 100);
        let isTrue = a > b;
        CORE_QUESTIONS.push({
            type: 'tf', section: 'TF',
            q: `True or False: The number ${a} is greater than ${b}.`,
            answer: isTrue ? 'true' : 'false'
        });
        currentCounts.TF++;
    }

    // Generate Short up to 300
    let shortWords = ['System', 'Object', 'String', 'Int32', 'Boolean', 'Console', 'Math', 'Array', 'Thread', 'Task'];
    while (currentCounts.Short < 300) {
        let w = shortWords[Math.floor(Math.random() * shortWords.length)];
        CORE_QUESTIONS.push({
            type: 'short', section: 'Short',
            q: `Type the word "${w}" to verify your typing skills:`,
            answer: w, accept: [w.toLowerCase()]
        });
        currentCounts.Short++;
    }

    // Generate Code up to 300
    while (currentCounts.Code < 300) {
        let a = Math.floor(Math.random() * 50) + 1;
        let b = Math.floor(Math.random() * 50) + 1;
        let operator = Math.random() > 0.5 ? '+' : '*';
        let result = operator === '+' ? a + b : a * b;
        CORE_QUESTIONS.push({
            type: 'mc', section: 'Code',
            code: `int x = ${a};\nint y = ${b};\nConsole.WriteLine(x ${operator} y);`,
            q: `What is the output?`,
            opts: [`${result}`, `${result + 10}`, `${Math.abs(result - 5)}`, `Error`],
            answer: `${result}`
        });
        currentCounts.Code++;
    }
}

// 3. RUN THE GENERATOR AND EXPORT TO THE APP
generateMissingQuestions();
QUESTIONS.push(...CORE_QUESTIONS);
